app.get('/api/products',auth,async(_,res)=>{const r=await pool.query('select p.id,p.code,p.name,p.unit,p.cost,p.price,p.min_stock,coalesce(sum(sb.quantity),0) stock from products p left join stock_balances sb on sb.product_id=p.id where p.is_active=true group by p.id order by p.name');res.json(r.rows)});
