app.get('/api/customers/:id/statement',auth,async(req,res)=>{const id=req.params.id;const r=await pool.query(`select i.id,i.invoice_no,'invoice' type,i.invoice_date date,i.total,coalesce((select sum(p.amount) from invoice_payments ip join payments p on p.id=ip.payment_id where ip.invoice_id=i.id),0) paid from invoices i where i.customer_id=$1 and i.invoice_type='sale' order by i.invoice_date desc`,[id]);const rows=r.rows.map(x=>({...x,balance:Number(x.total)-Number(x.paid)}));res.json({customerId:id,rows,total:Number(rows.reduce((a,x)=>a+Number(x.total),0)),paid:Number(rows.reduce((a,x)=>a+Number(x.paid),0)),balance:Number(rows.reduce((a,x)=>a+Number(x.balance),0))})});
app.get('/api/suppliers/:id/statement',auth,async(req,res)=>{const id=req.params.id;const r=await pool.query(`select i.id,i.invoice_no,'invoice' type,i.invoice_date date,i.total,coalesce((select sum(p.amount) from invoice_payments ip join payments p on p.id=ip.payment_id where ip.invoice_id=i.id),0) paid from invoices i where i.supplier_id=$1 and i.invoice_type='purchase' order by i.invoice_date desc`,[id]);const rows=r.rows.map(x=>({...x,balance:Number(x.total)-Number(x.paid)}));res.json({supplierId:id,rows,total:Number(rows.reduce((a,x)=>a+Number(x.total),0)),paid:Number(rows.reduce((a,x)=>a+Number(x.paid),0)),balance:Number(rows.reduce((a,x)=>a+Number(x.balance),0))})});
app.post('/api/customers',auth,requirePermission('customers.manage'),async(req,res)=>{const {name,phone,openingBalance=0,customerType='company'}=req.body||{};if(!name)return res.status(400).json({error:'اسم العميل مطلوب'});const r=await pool.query('insert into customers(name,phone,opening_balance,customer_type) values($1,$2,$3,$4) returning *',[name,phone,openingBalance,customerType]);res.status(201).json(r.rows[0])});
