app.get('/api/invoices',auth,async(req,res)=>{const type=req.query.type;const q=type?`select i.*,c.name customer_name,s.name supplier_name from invoices i left join customers c on c.id=i.customer_id left join suppliers s on s.id=i.supplier_id where i.invoice_type=$1 order by i.invoice_date desc,i.created_at desc`:`select i.*,c.name customer_name,s.name supplier_name from invoices i left join customers c on c.id=i.customer_id left join suppliers s on s.id=i.supplier_id order by i.invoice_date desc,i.created_at desc`;const r=await pool.query(q,type?[type]:[]);res.json(r.rows)});
